questions.modelAnswer:
func hammingWeight(_ n: Int) -> Int {
    var count = 0
    var val = n
    while val > 0 {
        val &= (val - 1)
        count += 1
    }
    return count
}
print("\(hammingWeight(11)) \(hammingWeight(128))")

