func findGCD(_ a: Int, _ b: Int) -> Int {
    return b == 0 ? a : findGCD(b, a % b)
}
func findLCM(_ a: Int, _ b: Int) -> Int {
    guard a != 0 && b != 0 else { return 0 }
    return abs(a * b) / findGCD(a, b)
}
print("gcd: \(findGCD(12, 18)), lcm: \(findLCM(12, 18))")

