// Print checkCollinear(line1) and checkCollinear(line2)

questions.modelAnswer:
func checkCollinear(_ p: [(Int, Int)]) -> Bool {
    guard p.count >= 3 else { return true }
    let dy1 = p[1].1 - p[0].1
    let dx1 = p[1].0 - p[0].0
    for i in 2..<p.count {
        let dy = p[i].1 - p[0].1
        let dx = p[i].0 - p[0].0
        if dy1 * dx != dy * dx1 { return false }
    }
    return true
}
let line1 = [(0, 0), (1, 1), (2, 2)]
let line2 = [(0, 0), (1, 1), (2, 3)]
